using System.Collections.Concurrent; using System.Diagnostics; using System.Globalization; using System.Text.Json; using Jellyfin.Data.Enums; using Jellyfin.Database.Implementations.Entities; using MediaBrowser.Common.Configuration; using MediaBrowser.Controller.Configuration; using MediaBrowser.Controller.Drawing; using MediaBrowser.Controller.Entities; using MediaBrowser.Controller.Library; using MediaBrowser.Controller.MediaEncoding; using MediaBrowser.Controller.Trickplay; using MediaBrowser.Model.Configuration; using MediaBrowser.Model.Drawing; using MediaBrowser.Model.Entities; using MediaBrowser.Model.Globalization; using MediaBrowser.Model.Tasks; using Microsoft.Extensions.Logging;
namespace Jellyfin.Plugin.TrickplayComplete.Tasks;
public sealed class CompleteMissingTrickplayTask : IScheduledTask, IConfigurableScheduledTask
{
 private const int PageSize=200; private readonly ILogger<CompleteMissingTrickplayTask> _log; private readonly ILibraryManager _library; private readonly ITrickplayManager _trickplay; private readonly IMediaEncoder _encoder; private readonly IImageEncoder _images; private readonly IServerConfigurationManager _server; private readonly IApplicationPaths _paths; private readonly object _statusGate=new(); private TaskStatusSnapshot _status=new("Idle",null,0,0,0,0,0,null,null,null); private readonly string _failureFile;
 public CompleteMissingTrickplayTask(ILogger<CompleteMissingTrickplayTask> log,ILibraryManager library,ITrickplayManager trickplay,IMediaEncoder encoder,IImageEncoder images,IServerConfigurationManager server,IApplicationPaths paths){_log=log;_library=library;_trickplay=trickplay;_encoder=encoder;_images=images;_server=server;_paths=paths;_failureFile=Path.Combine(paths.PluginConfigurationsPath,"TrickplayComplete.failures.json");}
 public string Name=>"Complete Missing Trickplay"; public string Key=>"CompleteMissingTrickplay"; public string Description=>"Generate only missing Jellyfin Trickplay resolutions with bounded, tolerant extraction."; public string Category=>"Library"; public bool IsHidden=>false; public bool IsEnabled=>Plugin.Instance?.Configuration.Enable??true; public bool IsLogged=>true;
 public IEnumerable<TaskTriggerInfo> GetDefaultTriggers()=>Array.Empty<TaskTriggerInfo>();
 public async Task ExecuteAsync(IProgress<double> progress,CancellationToken cancellationToken)
 {
  if(!IsEnabled){_log.LogInformation("Trickplay Complete is disabled.");return;}
  var started=DateTimeOffset.UtcNow; var options=_server.Configuration.TrickplayOptions; var desired=(options.WidthResolutions??Array.Empty<int>()).Where(w=>w>0).Distinct().ToArray();
  if(desired.Length==0){_log.LogInformation("No Jellyfin Trickplay WidthResolutions configured.");return;}
  SetStatus(new("Scanning",null,0,0,0,0,0,started,null,null)); _log.LogInformation("Scanning videos for missing Trickplay. Widths={Widths}, IntervalMs={Interval}, Tile={TileWidth}x{TileHeight}, SaveWithMedia={SaveWithMedia}",string.Join(',',desired),options.Interval,options.TileWidth,options.TileHeight,false);
  var existing=await LoadExistingAsync(cancellationToken).ConfigureAwait(false); var candidates=new List<WorkItem>(); var query=new InternalItemsQuery{MediaTypes=new[]{MediaType.Video},SourceTypes=new[]{SourceType.Library},IsVirtualItem=false,IsFolder=false,Recursive=true,Limit=PageSize}; var total=_library.GetCount(query); var scanned=0;
  while(scanned<total){cancellationToken.ThrowIfCancellationRequested();query.StartIndex=scanned;var page=_library.GetItemList(query).OfType<Video>().ToList();if(page.Count==0)break;foreach(var video in page){var lib=_library.GetLibraryOptions(video);if(lib is null||!lib.EnableTrickplayImageExtraction||!Eligible(video,options.Interval))continue;foreach(var requestedWidth in desired){var width=ActualWidth(video,requestedWidth);if(width>0&&!existing.Contains((video.Id,width)))candidates.Add(new WorkItem(video,lib,width));}scanned+=page.Count;SetStatus(new("Scanning",null,scanned,total,0,0,0,started,null,null));progress.Report(total==0?0:Math.Min(20d,20d*scanned/total));}
  _log.LogInformation("Trickplay scan complete. Videos={Videos}, Missing={Missing}",scanned,candidates.Count); if(candidates.Count==0){SetStatus(new("Completed",null,0,0,0,0,0,started,DateTimeOffset.UtcNow,null));progress.Report(100);return;}
  var success=0;var failed=0;var skipped=0;var done=0;var failures=LoadFailures();var maxDegree=Math.Clamp(Plugin.Instance?.Configuration.ConcurrentJobs??1,1,4);using var gate=new SemaphoreSlim(maxDegree,maxDegree);var jobs=candidates.Select(async item=>{await gate.WaitAsync(cancellationToken).ConfigureAwait(false);try{var key=(item.Video.Id,item.Width);if(IsPaused(failures,key,item.Video.Path)){Interlocked.Increment(ref skipped);return;}try{await GenerateAsync(item.Video,item.Library,item.Width,options,cancellationToken).ConfigureAwait(false);failures.Remove(key);Interlocked.Increment(ref success);}catch(Exception ex){RecordFailure(failures,item,key,ex);Interlocked.Increment(ref failed);_log.LogError(ex,"Trickplay generation failed. Item={ItemId}, Width={Width}, Path={Path}",item.Video.Id,item.Width,item.Video.Path);}}finally{var n=Interlocked.Increment(ref done);SetStatus(new("Generating",item.Video.Path,n,candidates.Count,success,failed,skipped,started,null,null));progress.Report(20d+80d*n/candidates.Count);gate.Release();}});await Task.WhenAll(jobs).ConfigureAwait(false);SaveFailures(failures);var finished=DateTimeOffset.UtcNow;SetStatus(new("Completed",null,candidates.Count,candidates.Count,success,failed,skipped,started,finished,null));_log.LogInformation("Trickplay completion finished. Missing={Missing}, Success={Success}, Failed={Failed}, Skipped={Skipped}, Elapsed={Elapsed}",candidates.Count,success,failed,skipped,finished-started);progress.Report(100);
 }
 private async Task<HashSet<(Guid,int)>> LoadExistingAsync(CancellationToken ct){var result=new HashSet<(Guid,int)>();var offset=0;while(true){var page=await _trickplay.GetTrickplayItemsAsync(500,offset).ConfigureAwait(false);foreach(var x in page)result.Add((x.ItemId,x.Width));if(page.Count<500)break;offset+=page.Count;ct.ThrowIfCancellationRequested();}return result;}
 private async Task GenerateAsync(Video video,LibraryOptions library, int width,TrickplayOptions options,CancellationToken outer)
 {
  var source=video.GetMediaSources(false).FirstOrDefault(s=>!s.IsRemote&&Guid.TryParse(s.Id,out var id)&&id==video.Id);if(source is null||string.IsNullOrWhiteSpace(source.Path)||!File.Exists(source.Path))throw new FileNotFoundException("No local media source",video.Path);var stream=source.VideoStream??video.GetMediaStreams().FirstOrDefault(s=>s.Type==MediaStreamType.Video);if(stream is null)throw new InvalidOperationException("No video stream");var temp=Path.Combine(_paths.TempDirectory,"trickplay-complete",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);var timeout=TimeSpan.FromMinutes(Math.Max(1,Plugin.Instance?.Configuration.MaxJobMinutes??30));var maxBytes=Math.Max(16L*1024*1024,Plugin.Instance?.Configuration.MaxTemporarySizeBytes??2147483648);var maxFrames=Math.Max(1,Plugin.Instance?.Configuration.MaxFrames??20000);var threads=Math.Clamp(Plugin.Instance?.Configuration.FFmpegThreads??2,1,16);var interval=Math.Max(1000,options.Interval)/1000d;var psi=new ProcessStartInfo{FileName=_encoder.EncoderPath,UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true};foreach(var a in new[]{"-nostdin","-hide_banner","-loglevel","error","-fflags","+genpts+discardcorrupt","-err_detect","ignore_err","-threads",threads.ToString(CultureInfo.InvariantCulture),"-i",source.Path,"-an","-sn","-vf",$"fps=1/{interval.ToString(CultureInfo.InvariantCulture)},scale={width}:-2:flags=bicubic","-vsync","0","-frames:v",maxFrames.ToString(CultureInfo.InvariantCulture),"-q:v",Math.Clamp(options.Qscale,1,31).ToString(CultureInfo.InvariantCulture),"-f","image2",Path.Combine(temp,"%08d.jpg")})psi.ArgumentList.Add(a);_log.LogInformation("Trickplay FFmpeg start. Item={ItemId}, Width={Width}, Encoder={Encoder}, Args={Args}",video.Id,width,_encoder.EncoderPath,string.Join(" ",psi.ArgumentList));using var process=new Process{StartInfo=psi,EnableRaisingEvents=true};var sw=Stopwatch.StartNew();process.Start();var stderrTask=process.StandardError.ReadToEndAsync();try{while(!process.HasExited){outer.ThrowIfCancellationRequested();if(sw.Elapsed>timeout)throw new TimeoutException($"FFmpeg exceeded {timeout}");if(DirectorySize(temp)>maxBytes)throw new IOException($"Temporary output exceeded {maxBytes} bytes");await Task.Delay(500,outer).ConfigureAwait(false);}await process.WaitForExitAsync(outer).ConfigureAwait(false);var stderr=await stderrTask.ConfigureAwait(false);if(process.ExitCode!=0)throw new InvalidOperationException($"FFmpeg exit {process.ExitCode}: {stderr.Trim()}");var paths=Directory.EnumerateFiles(temp,"*.jpg").OrderBy(x=>x,StringComparer.Ordinal).Where(IsJpeg).ToList();if(paths.Count==0)throw new InvalidOperationException("FFmpeg produced no valid JPEG frames");var output=_trickplay.GetTrickplayDirectory(video,options.TileWidth,options.TileHeight,width,library.SaveTrickplayWithMedia);var info=_trickplay.CreateTiles(paths,width,options,output);if(info is null||info.ThumbnailCount<=0||!Directory.EnumerateFiles(output,"*.jpg").Any())throw new InvalidOperationException("CreateTiles produced no usable tile");info.ItemId=video.Id;await _trickplay.SaveTrickplayInfo(info).ConfigureAwait(false);_log.LogInformation("Trickplay generated. Item={ItemId}, Width={Width}, Frames={Frames}, Elapsed={Elapsed}",video.Id,width,paths.Count,sw.Elapsed);}catch{Kill(process);throw;}finally{try{if(Directory.Exists(temp))Directory.Delete(temp,true);}catch(Exception ex){_log.LogWarning(ex,"Failed to clean temp directory {Temp}",temp);}}
 }
 private static bool Eligible(Video v,int interval)=>v.VideoType!=VideoType.Iso&&v.VideoType!=VideoType.Dvd&&v.VideoType!=VideoType.BluRay&&!v.IsPlaceHolder&&!v.IsShortcut&&v.IsCompleteMedia&&v.RunTimeTicks.HasValue&&v.RunTimeTicks.Value>=TimeSpan.FromMilliseconds(interval).Ticks&&v.GetMediaStreams().Any(s=>s.Type==MediaStreamType.Video);
 private static int ActualWidth(Video v,int requested){var source=v.GetMediaSources(false).FirstOrDefault();var w=source?.VideoStream?.Width??requested;return Math.Max(2,2*(Math.Min(requested,w)/2));}
 private static bool IsJpeg(string p){try{using var f=File.OpenRead(p);if(f.Length<4)return false;var b=new byte[2];f.ReadExactly(b);f.Seek(-2,SeekOrigin.End);var e=new byte[2];f.ReadExactly(e);return b[0]==0xff&&b[1]==0xd8&&e[0]==0xff&&e[1]==0xd9;}catch{return false;}}
 private static long DirectorySize(string d)=>Directory.Exists(d)?Directory.EnumerateFiles(d,"*",SearchOption.AllDirectories).Sum(p=>{try{return new FileInfo(p).Length;}catch{return 0;}}):0;
 private static void Kill(Process p){try{if(!p.HasExited)p.Kill(true);}catch{}try{p.WaitForExit(2000);}catch{}}
 private sealed record WorkItem(Video Video,LibraryOptions Library,int Width);
 private sealed record Failure(Guid ItemId,int Width,int Count,long Size,DateTime LastWrite,string Error,DateTimeOffset LastAttempt);
 private Dictionary<(Guid,int),Failure> LoadFailures(){try{if(File.Exists(_failureFile)){var a=JsonSerializer.Deserialize<List<Failure>>(File.ReadAllText(_failureFile))??new();return a.ToDictionary(x=>(x.ItemId,x.Width));}}catch(Exception ex){_log.LogWarning(ex,"Unable to load failure records");}return new();}
 private void SaveFailures(Dictionary<(Guid,int),Failure> f){try{Directory.CreateDirectory(Path.GetDirectoryName(_failureFile)!);File.WriteAllText(_failureFile,JsonSerializer.Serialize(f.Values,new JsonSerializerOptions{WriteIndented=true}));}catch(Exception ex){_log.LogWarning(ex,"Unable to save failure records");}}
 private bool IsPaused(Dictionary<(Guid,int),Failure> f,(Guid,int) key,string path){if(!f.TryGetValue(key,out var x)||x.Count<(Plugin.Instance?.Configuration.MaxRetries??3))return false;try{var fi=new FileInfo(path);if(Plugin.Instance?.Configuration.RetryAfterFileChanged==true&&(fi.Length!=x.Size||fi.LastWriteTimeUtc!=x.LastWrite))return false;}catch{}return true;}
 private void RecordFailure(Dictionary<(Guid,int),Failure> f,WorkItem item,(Guid,int) key,Exception ex){try{var fi=new FileInfo(item.Video.Path);f[key]=new Failure(item.Video.Id,item.Width,(f.TryGetValue(key,out var old)?old.Count:0)+1,fi.Exists?fi.Length:0,fi.Exists?fi.LastWriteTimeUtc:DateTime.MinValue,ex.Message,DateTimeOffset.UtcNow);}catch{} }
 private void SetStatus(TaskStatusSnapshot s){lock(_statusGate)_status=s;}
 private sealed record TaskStatusSnapshot(string Phase,string? CurrentFile,int Completed,int Total,int Success,int Failed,int Skipped,DateTimeOffset? Started,DateTimeOffset? Finished,string? Error);
}